fn choose_num(x: i8, y: i8) -> i8 {
    // If the lower bound exceeds the upper bound, there's no valid interval.
    if x > y {
        return -1;
    }

    // Compute the largest even integer <= y.
    // If y is even, use y; otherwise, subtract 1 to get the next lower even.
    let candidate = if y % 2 == 0 { y } else { y - 1 };

    // If this candidate still lies in [x, y], it's our answer; otherwise, no even
    // integer is in the interval.
    if candidate >= x {
        candidate
    } else {
        -1
    }
}

